package dk.jamesbabz.madkursus.outbound.recipetemplate.details;
import java.util.*;import jakarta.persistence.*;import lombok.*;import dk.jamesbabz.madkursus.service.models.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="recipe_template_steps") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class RecipeTemplateStepEntity{@Id private UUID id;@ManyToOne(optional=false)@JoinColumn(name="recipe_template_id")private RecipeTemplateEntity recipeTemplate;@Enumerated(EnumType.STRING)private RecipeStepType stepType;private String instruction;@JdbcTypeCode(SqlTypes.JSON)private RecipeStructuredInstruction structuredInstruction;private int sortOrder;private UUID cookingProcessId;@OneToMany(mappedBy="recipeTemplateStep")private List<RecipeTemplateProcessBindingEntity> bindings=new ArrayList<>();}
